    "contracts/VoterV5/VotingEscrow/IVotingEscrowV2_Storage.sol": {
      "content": "// SPDX-License-Identifier: MIT
pragma solidity 0.8.13;

import {IProtocolToken} from "../../interfaces/IProtocolToken.sol";
